from PIL import Image
import numpy as np
im = Image.open('radiograph.jpg').convert('L')
def prep(crop, p=3):
    a = np.asarray(crop).astype(np.float32)
    p2,p98 = np.percentile(a,p), np.percentile(a,100-p)
    a = np.clip((a-p2)/(p98-p2),0,1)
    return Image.fromarray((a*255).astype('uint8'))
regions = {
 'S_ur_premolars': (800, 380, 1050, 620),
 'T_ul_canine': (1350, 380, 1600, 620),
}
for name,(x1,y1,x2,y2) in regions.items():
    c = im.crop((x1,y1,x2,y2))
    c = c.resize((c.width*4, c.height*4), Image.LANCZOS)
    c = prep(c)
    c.save(f'crops/{name}.png')
print('done')
